// Generated by Agent: SETUP | Framework: myrmion-AI-factory | Feature: EVOL-106 — framework-shipped Playwright clause helper (proof at the close).
//
// A test proves case F/C when its title opens with `[F/C]` and its steps are the case's clauses, in order:
// one `given` / `when` / `then` per clause, the clause text verbatim (an `And` / `But` takes the keyword before it).
// `gate.py proof` reads the JSON reporter and judges the steps, the `asserted` marks and the control run.
//
//   then   counts the assertions made through this module's `expect` and marks the step `asserted`;
//          a Then that asserts nothing throws — it proves nothing.
//   control(page, url, mutate)  acts only under CASE_CONTROL=1: it corrupts the decisive response
//          (fetch, mutate, fulfil) and marks the test `control`. The control run must fail on a Then.
import { test, expect as base, type Page } from '@playwright/test';

let assertions = 0;

function counted<T>(m: T): T {
  if (m === null || (typeof m !== 'object' && typeof m !== 'function')) return m;
  return new Proxy(m as object, {
    get(target, prop, receiver) {
      const v = Reflect.get(target, prop, receiver);
      if (typeof v === 'function') {
        return (...args: unknown[]) => {
          assertions += 1;
          return Reflect.apply(v, target, args);
        };
      }
      return v !== null && typeof v === 'object' ? counted(v) : v;
    },
  }) as T;
}

/** Playwright's `expect`, counted: every matcher call (`.not`, `.resolves`, `.soft`, `.poll` included) counts. */
export const expect = new Proxy(base, {
  apply(target, self, args) {
    return counted(Reflect.apply(target, self, args));
  },
  get(target, prop, receiver) {
    const v = Reflect.get(target, prop, receiver);
    if (prop === 'soft' || prop === 'poll') {
      return (...args: unknown[]) => counted(Reflect.apply(v as (...a: unknown[]) => unknown, target, args));
    }
    return v;
  },
}) as typeof base;

export async function given(text: string, body: () => Promise<void>): Promise<void> {
  await test.step(`Given ${text}`, body);
}

export async function when(text: string, body: () => Promise<void>): Promise<void> {
  await test.step(`When ${text}`, body);
}

export async function then(text: string, body: () => Promise<void>): Promise<void> {
  const title = `Then ${text}`;
  await test.step(title, async () => {
    const before = assertions;
    try {
      await body();
    } finally {
      if (assertions > before) test.info().annotations.push({ type: 'asserted', description: title });
    }
    if (assertions === before) throw new Error(`${title}: no assertion — a Then that asserts nothing proves nothing`);
  });
}

/** Under CASE_CONTROL=1, corrupt the responses matching `url` with `mutate` and mark the test `control`. */
export async function control(page: Page, url: string | RegExp, mutate: (body: string) => string): Promise<void> {
  if (process.env.CASE_CONTROL !== '1') return;
  test.info().annotations.push({ type: 'control', description: String(url) });
  await page.route(url, async (route) => {
    const response = await route.fetch();
    await route.fulfill({ response, body: mutate(await response.text()) });
  });
}
